add_filter( 'manage_edit-product_columns', 'perfectpixel_products_meta_column', 20 );
add_action( 'manage_product_posts_custom_column', 'perfectpixel_products_meta_column_value', 10, 2 );
add_filter( 'manage_edit-product_sortable_columns', 'perfectpixel_products_meta_column_sortable' );
add_action( 'pre_get_posts', 'perfectpixel_products_meta_column_orderby' );

function perfectpixel_products_meta_column( $columns ) {
	$new = array();
	foreach ( $columns as $key => $label ) {
		$new[ $key ] = $label;
		if ( 'sku' === $key ) {
			$new['perfectpixel_meta'] = '{{products_column_label}}';
		}
	}
	if ( ! isset( $new['perfectpixel_meta'] ) ) {
		$new['perfectpixel_meta'] = '{{products_column_label}}';
	}
	return $new;
}

function perfectpixel_products_meta_column_value( $column, $post_id ) {
	if ( 'perfectpixel_meta' === $column ) {
		$value = get_post_meta( $post_id, sanitize_text_field( '{{products_column_meta_key}}' ), true );
		echo '' !== (string) $value ? esc_html( is_scalar( $value ) ? $value : wp_json_encode( $value ) ) : '&ndash;';
	}
}

function perfectpixel_products_meta_column_sortable( $columns ) {
	$columns['perfectpixel_meta'] = 'perfectpixel_meta';
	return $columns;
}

function perfectpixel_products_meta_column_orderby( $query ) {
	if ( is_admin() && $query->is_main_query() && 'perfectpixel_meta' === $query->get( 'orderby' ) ) {
		$query->set( 'meta_key', sanitize_text_field( '{{products_column_meta_key}}' ) );
		$query->set( 'orderby', 'meta_value' );
	}
}
